import sys; sys.path.insert(0,'/home/claude/honglifecalc/build')
from enrich_lib import build, table, faq_html
calc='''function calc(){const s=num('s'),b=num('b'),th=+$('sl').value,x=s+b,L=v=>th?Math.max(0,v-th)*.09:0;
 const tx=itax(x).tax-itax(s).tax,n=ni(x)-ni(s),l=L(x)-L(s),k=b-tx-n-l,lost=pa(s)-pa(x);
 return big('Bonus you keep',gbp(k,0),pc(k/Math.max(b,1),0)+' of '+gbp(b,0))+kv([['Income tax on bonus',gbp(tx,0),'neg'],['Employee National Insurance on bonus',gbp(n,0),'neg']].concat(th?[['Student loan on bonus (9%)',gbp(l,0),'neg']]:[]).concat(lost>0?[['Personal allowance lost',gbp(lost,0),'neg']]:[]).concat([['Total deductions',gbp(tx+n+l,0),'t'],['Effective rate on the bonus',pc((b-k)/Math.max(b,1),0)],['If sacrificed into pension',gbp(b,0)+' goes in instead of '+gbp(k,0)+' cash','pos']]))+'<p class="note">2026/27 rates for England, Wales and Northern Ireland: 20% / 40% / 45% income tax, 8% / 2% employee NI. Scottish income tax bands differ. Payroll may over-deduct in the bonus month; it evens out over the tax year with a cumulative tax code.</p>'}'''
FAQ=[
("How much of an £8,000 bonus on a £60,000 salary do I keep?","£4,640, or 58%. The whole bonus falls in the higher-rate band, so it pays 40% income tax (£3,200) and 2% National Insurance (£160). With a Plan 2 student loan a further 9% (£720) is deducted and you keep £3,920."),
("Are bonuses taxed at a higher rate in the UK?","No. A bonus is added to your other pay for the tax year and taxed at your normal marginal rates — 20%, 40% or 45% income tax plus 8% or 2% employee National Insurance. It only feels higher because the bonus can push part of your income into a higher band, and because the bonus month's payroll can over-deduct."),
("Why was so much tax taken off my bonus?","PAYE works out tax month by month. A large bonus paid in one month can make that month look like a much higher annual salary, so more tax is deducted. On a normal cumulative tax code the extra is usually given back through lower deductions in later months, or by HMRC after the end of the tax year."),
("What if my bonus takes me over £100,000?","Between £100,000 and £125,140 you lose £1 of personal allowance for every £2 of income, so that slice of a bonus is taxed at an effective 60% plus 2% NI. A £10,000 bonus on £110,000 leaves you £3,800 (38%). Sacrificing the bonus into a pension, if your employer allows it, keeps your adjusted net income lower and protects the allowance."),
("Can I avoid tax on a bonus by paying it into my pension?","With bonus sacrifice you give up the bonus before it is paid and your employer pays it into your pension instead. You pay no income tax or National Insurance on it at that point, and some employers also add the employer NI they save (15% above the £5,000 secondary threshold in 2026/27). Pension savings are taxed when you take them out, apart from the tax-free portion. From April 2029 the NI saving will only apply to the first £2,000 a year sacrificed."),
("Do I pay student loan on my bonus?","Yes. Student loan repayments are 9% of income above your plan's threshold (6% above £21,000 for a Postgraduate Loan), and the bonus counts as income. If you are already above the threshold, 9% of the whole bonus goes on repayments.")]
art='''<h2>How a bonus is taxed in the UK (2026/27)</h2>
<p>There is no special bonus tax. Your bonus is added to your salary for the tax year and taxed through PAYE like any other pay: income tax at your marginal rate, employee National Insurance and, if you have one, student loan repayments. This calculator works out the extra tax caused by the bonus as <b>tax on (salary + bonus) − tax on salary</b>, which is exactly how much of the bonus you keep over the year.</p>
<h3>Rates applied to a bonus</h3>
'''+table(['Your total pay (salary + bonus)','Income tax','Employee NI','Typical share of the bonus you keep'],[['£12,571 – £50,270','20% (basic rate)','8%','72%'],['£50,271 – £100,000','40% (higher rate)','2%','58%'],['£100,001 – £125,140','40% + loss of personal allowance = effective 60%','2%','38%'],['Over £125,140','45% (additional rate)','2%','53%']])+'''
<p class="note">England, Wales and Northern Ireland. The personal allowance (£12,570), higher-rate threshold (£50,270) and additional-rate threshold (£125,140) are frozen. Scottish taxpayers pay Scottish income tax rates and bands on non-savings income, so their share kept is different; National Insurance is the same across the UK. Student loan adds 9% on top for anyone above their plan threshold.</p>
<h3>Scottish income tax bands 2026/27</h3>
'''+table(['Band','Rate','Taxable income (above the personal allowance)','Salary with the full £12,570 allowance'],[['Starter','19%','up to £3,967','£12,571 – £16,537'],['Basic','20%','£3,968 – £16,956','£16,538 – £29,526'],['Intermediate','21%','£16,957 – £31,092','£29,527 – £43,662'],['Higher','42%','£31,093 – £62,430','£43,663 – £75,000'],['Advanced','45%','£62,431 – £125,140','£75,001 – £125,140'],['Top','48%','over £125,140','over £125,140']])+'''
<p class="note">This calculator uses England, Wales and Northern Ireland rates. For a Scottish taxpayer, a bonus that falls between £43,663 and £75,000 of total pay is taxed at 42% plus 2% NI (keeps 56%), and from £75,001 at 45% plus 2% NI (keeps 53%), before any student loan. The personal allowance taper above £100,000 applies in Scotland too.</p>
<h3>Worked examples (calculator results)</h3>
'''+table(['Salary','Bonus','Income tax','NI','Student loan','You keep'],[['£30,000','£2,000','£400','£160','—','£1,440 (72%)'],['£45,000','£5,000','£1,000','£400','—','£3,600 (72%)'],['£40,000','£5,000','£1,000','£400','£450 (Plan 2)','£3,150 (63%)'],['£60,000','£8,000','£3,200','£160','—','£4,640 (58%)'],['£95,000','£10,000','£5,000','£200','—','£4,800 (48%)'],['£110,000','£10,000','£6,000','£200','—','£3,800 (38%)'],['£130,000','£20,000','£9,000','£400','—','£10,600 (53%)']])+'''
<p class="note">£95,000 + £10,000: the first £5,000 is taxed at 40%, and the £5,000 above £100,000 also costs £2,500 of personal allowance, taxed at 40% (£1,000 extra). £110,000 + £10,000 sits entirely in the 60% zone.</p>
<h3>Student loan thresholds 2026/27</h3>
'''+table(['Plan','Annual threshold','Rate on income above it'],[['Plan 1','£26,900','9%'],['Plan 2','£29,385','9%'],['Plan 4 (Scotland)','£33,795','9%'],['Plan 5','£25,000','9%'],['Postgraduate Loan','£21,000','6% (not in this calculator)']])+'''
<h3>Why your bonus payslip looks worse than this</h3>
<ul><li><b>Monthly PAYE:</b> in the bonus month your pay is compared with one-twelfth of the annual bands, so more of the bonus can be taxed at 40% or 45% than over the full year. With a cumulative tax code (e.g. 1257L) this corrects itself in later months.</li><li><b>Emergency or week 1/month 1 codes:</b> no cumulative correction is made through payroll; you may need to claim a refund from HMRC after the tax year ends (via your personal tax account).</li><li><b>Student loan is not cumulative:</b> it is worked out per pay period, so a large one-off bonus can trigger repayments in that month even if your annual income is below the threshold. You can ask the Student Loans Company for a refund if your annual income ends up under it.</li></ul>
<h3>Ways to keep more of a bonus</h3>
<ul><li><b>Bonus sacrifice into a pension:</b> the whole bonus goes into your pension with no income tax or employee NI. Ask whether your employer passes on its 15% employer NI saving.</li><li><b>Personal pension contribution:</b> if sacrifice isn't offered, a contribution to a relief-at-source pension gets 20% added and higher-rate relief claimed back — useful to bring income below £100,000 and recover the personal allowance.</li><li><b>Check child benefit:</b> a bonus counts towards the adjusted net income used for the High Income Child Benefit Charge and can push you over its threshold.</li><li><b>Cycle to work, share schemes or electric car salary sacrifice</b> may also be offered as alternatives to cash.</li></ul>
'''+faq_html(FAQ)+'''
<p class="note">Sources (checked 22 Nov 2026): <a href="https://www.gov.uk/guidance/rates-and-thresholds-for-employers-2026-to-2027" rel="nofollow">HMRC — Rates and thresholds for employers 2026 to 2027</a> (income tax and Scottish bands, NI 8%/2% and employer 15% above £5,000, student loan thresholds); <a href="https://www.gov.uk/government/publications/budget-2026-overview-of-tax-legislation-and-rates-ootlar/annex-a-rates-and-allowances" rel="nofollow">Budget 2026 — Annex A: rates and allowances</a> (personal allowance taper above £100,000); <a href="https://www.gov.uk/government/publications/changes-to-salary-sacrifice-for-pensions-from-april-2029" rel="nofollow">HM Treasury — Changes to salary sacrifice for pensions from April 2029</a>. Estimates only — not tax advice.</p>'''
out=build('/uk/bonus-tax-calculator.html','Bonus Tax Calculator UK 2026/27 – How Much of My Bonus Do I Keep?',
 'How much of your bonus you keep in 2026/27 after 20%/40%/45% income tax, 8%/2% NI and student loan, with examples, the 60% trap over £100,000 and pension sacrifice.',art,FAQ,calc=calc)
s=open(out,encoding='utf-8').read()
old='h=Math.min(Math.max(0,t-37700),125140-37700-(12570-p))'
assert old in s
s=s.replace(old,'h=Math.min(Math.max(0,t-37700),125140-37700)')
open(out,'w',encoding='utf-8').write(s);print(out)
